REVOKE INSERT,UPDATE,DELETE ON public.digital_guide_download_events FROM authenticated,anon;GRANT SELECT ON public.digital_guide_download_events TO authenticated;
CREATE FUNCTION public.facility_agreement_insert_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.scope_fingerprint IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_relationship_events e WHERE e.action='facility_quote_proposed' AND e.id::text=NEW.quote_reference AND e.workspace_id=NEW.facility_workspace_id AND (e.details->>'providerId')::uuid=NEW.provider_workspace_id AND (e.details->>'providerActor')::uuid=NEW.provider_confirmed_by AND e.details->>'scope'=NEW.scope_fingerprint AND (e.details->>'totalCents')::bigint=NEW.approved_total_cents AND e.details->>'policy'=NEW.provider_policy_snapshot AND NEW.facility_confirmed_by=auth.uid() AND public.can_manage_account_connections(NEW.facility_workspace_id)) THEN RAISE EXCEPTION 'Exact bilateral quote confirmation required';END IF;RETURN NEW;END $$;
CREATE TRIGGER facility_exact_confirmation BEFORE INSERT ON public.provider_facility_agreement_versions FOR EACH ROW EXECUTE FUNCTION public.facility_agreement_insert_guard();